WITH metrics AS (SELECT id, device_code, reading_ts, temp_c, humidity, pressure, status_bits, firmware, AVG(humidity) OVER (PARTITION BY device_code) AS device_code_avg_humidity, AVG(humidity) OVER (PARTITION BY device_code ORDER BY CAST(reading_ts AS BIGINT) RANGE BETWEEN 3600 PRECEDING AND CURRENT ROW) AS humidity_avg_1h, LEAD(pressure, 2) OVER w_running AS next_pressure, SUM(temp_c) OVER (PARTITION BY device_code ORDER BY pressure, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_temp_c FROM device_readings WINDOW w_running AS (PARTITION BY device_code ORDER BY status_bits, id)) SELECT device_code, DATE_TRUNC('HOUR', reading_ts) AS hour_window, MAX(device_code_avg_humidity) FILTER (WHERE device_code = 'DV-03') AS dv_03_max_device_code_avg_humidity, MAX(reading_ts) AS last_reading_ts, PERCENT_RANK() OVER (PARTITION BY device_code ORDER BY MAX(device_code_avg_humidity) FILTER (WHERE device_code = 'DV-03') DESC) AS dv_03_max_device_code_avg_humidity_percent_rank FROM metrics GROUP BY device_code, hour_window;
